@page "/dispatcher"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h1>Dispatcher Dashboard</h1>

<div class="row mb-3">
    <div class="col-md-6">
        <input type="text" class="form-control" placeholder="Filter by destination..."
               @bind="filterText" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="filterStatus">
            <option value="">All Statuses</option>
            @foreach (var status in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@status">@status</option>
            }
        </select>
    </div>
    <div class="col-md-3">
        <button class="btn btn-success w-100" @onclick="ShowCreateForm">
            + New Shipment
        </button>
    </div>
</div>

@if (showCreateForm)
{
    <div class="card mb-4">
        <div class="card-header">Create New Shipment</div>
        <div class="card-body">
            <div class="row g-3">
                <div class="col-md-4">
                    <label class="form-label">Origin</label>
                    <input type="text" class="form-control" @bind="newShipment.Origin" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Destination</label>
                    <input type="text" class="form-control" @bind="newShipment.Destination" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Customer Email</label>
                    <input type="email" class="form-control" @bind="newShipment.CustomerEmail" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Description</label>
                    <input type="text" class="form-control" @bind="newShipment.Description" />
                </div>
                <div class="col-md-3">
                    <label class="form-label">Est. Delivery</label>
                    <input type="date" class="form-control" @bind="estimatedDeliveryDate" />
                </div>
                <div class="col-md-3 d-flex align-items-end gap-2">
                    <button class="btn btn-primary" @onclick="CreateShipment">Create</button>
                    <button class="btn btn-secondary" @onclick="CancelCreate">Cancel</button>
                </div>
            </div>
        </div>
    </div>
}

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Customer</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var shipment in FilteredShipments)
                {
                    <tr>
                        <td><code>@shipment.TrackingNumber</code></td>
                        <td>@shipment.Origin</td>
                        <td>@shipment.Destination</td>
                        <td>@shipment.CustomerEmail</td>
                        <td><span class="badge bg-@GetStatusColor(shipment.Status)">@shipment.Status</span></td>
                        <td>@shipment.EstimatedDelivery?.ToString("yyyy-MM-dd")</td>
                        <td>
                            <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                    value="@shipment.Status"
                                    @onchange="e => UpdateStatus(shipment.Id, e)">
                                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@status" selected="@(shipment.Status == status)">@status</option>
                                }
                            </select>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    @if (!FilteredShipments.Any())
    {
        <div class="alert alert-info">No shipments match your filter criteria.</div>
    }
}

@code {
    private List<Shipment>? shipments;
    private string filterText = "";
    private string filterStatus = "";
    private bool showCreateForm;
    private Shipment newShipment = new();
    private DateTime? estimatedDeliveryDate;

    private IEnumerable<Shipment> FilteredShipments => shipments?.Where(s =>
        (string.IsNullOrEmpty(filterText) || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)) &&
        (string.IsNullOrEmpty(filterStatus) || s.Status.ToString() == filterStatus)
    ) ?? [];

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private void ShowCreateForm() => showCreateForm = true;
    private void CancelCreate()
    {
        showCreateForm = false;
        newShipment = new();
        estimatedDeliveryDate = null;
    }

    private async Task CreateShipment()
    {
        newShipment.EstimatedDelivery = estimatedDeliveryDate;
        await ShipmentService.CreateShipmentAsync(newShipment);
        shipments = await ShipmentService.GetAllShipmentsAsync();
        CancelCreate();
    }

    private async Task UpdateStatus(int id, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var status))
        {
            await ShipmentService.UpdateShipmentStatusAsync(id, status);
            var shipment = shipments?.FirstOrDefault(s => s.Id == id);
            if (shipment is not null) shipment.Status = status;
        }
    }

    private static string GetStatusColor(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "secondary",
        ShipmentStatus.PickedUp => "info",
        ShipmentStatus.InTransit => "primary",
        ShipmentStatus.OutForDelivery => "warning",
        ShipmentStatus.Delivered => "success",
        ShipmentStatus.Delayed => "danger",
        _ => "secondary"
    };
}

@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@using Microsoft.AspNetCore.Components.Authorization
@attribute [Microsoft.AspNetCore.Authorization.Authorize]
@inject IShipmentService ShipmentService
@inject AuthenticationStateProvider AuthStateProvider

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>

<div class="row mb-4">
    <div class="col-md-8">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g. SHP-20260711-123456)"
                   @bind="trackingNumber" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="SearchByTracking">Track</button>
        </div>
    </div>
</div>

@if (searchPerformed && trackedShipment is null)
{
    <div class="alert alert-warning">
        No shipment found with tracking number "<strong>@searchedNumber</strong>".
    </div>
}

@if (trackedShipment is not null)
{
    <div class="card mb-4">
        <div class="card-header">
            <strong>Tracking: @trackedShipment.TrackingNumber</strong>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Status</dt>
                        <dd><span class="badge bg-@GetStatusColor(trackedShipment.Status) fs-6">@trackedShipment.Status</span></dd>
                        <dt>Origin</dt>
                        <dd>@trackedShipment.Origin</dd>
                        <dt>Destination</dt>
                        <dd>@trackedShipment.Destination</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Description</dt>
                        <dd>@(string.IsNullOrEmpty(trackedShipment.Description) ? "—" : trackedShipment.Description)</dd>
                        <dt>Shipped On</dt>
                        <dd>@trackedShipment.CreatedAt.ToString("MMMM dd, yyyy")</dd>
                        <dt>Estimated Delivery</dt>
                        <dd class="fw-bold text-primary">
                            @(trackedShipment.EstimatedDelivery?.ToString("MMMM dd, yyyy") ?? "Not yet determined")
                        </dd>
                    </dl>
                </div>
            </div>
            @{
                var progress = GetProgressPercentage(trackedShipment.Status);
            }
            <div class="progress mt-3" style="height: 25px;">
                <div class="progress-bar bg-@GetStatusColor(trackedShipment.Status)"
                     role="progressbar"
                     style="width: @progress%"
                     aria-valuenow="@progress" aria-valuemin="0" aria-valuemax="100">
                    @trackedShipment.Status
                </div>
            </div>
        </div>
    </div>
}

<hr class="my-4" />

<h2>My Shipments</h2>

@if (myShipments is null)
{
    <p><em>Loading your shipments...</em></p>
}
else if (!myShipments.Any())
{
    <div class="alert alert-info">You have no shipments associated with your account.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped">
            <thead>
                <tr>
                    <th>Tracking #</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var shipment in myShipments)
                {
                    <tr @onclick="() => ViewShipment(shipment)" style="cursor: pointer;">
                        <td><code>@shipment.TrackingNumber</code></td>
                        <td>@shipment.Destination</td>
                        <td><span class="badge bg-@GetStatusColor(shipment.Status)">@shipment.Status</span></td>
                        <td>@(shipment.EstimatedDelivery?.ToString("yyyy-MM-dd") ?? "TBD")</td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@code {
    private string trackingNumber = "";
    private string searchedNumber = "";
    private bool searchPerformed;
    private Shipment? trackedShipment;
    private List<Shipment>? myShipments;

    protected override async Task OnInitializedAsync()
    {
        var authState = await AuthStateProvider.GetAuthenticationStateAsync();
        var email = authState.User.Identity?.Name ?? "";
        if (!string.IsNullOrEmpty(email))
        {
            myShipments = await ShipmentService.GetShipmentsForCustomerAsync(email);
        }
        else
        {
            myShipments = [];
        }
    }

    private async Task SearchByTracking()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        searchedNumber = trackingNumber.Trim();
        trackedShipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
        searchPerformed = true;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await SearchByTracking();
    }

    private void ViewShipment(Shipment shipment)
    {
        trackedShipment = shipment;
        trackingNumber = shipment.TrackingNumber;
        searchedNumber = shipment.TrackingNumber;
        searchPerformed = true;
    }

    private static int GetProgressPercentage(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Delayed => 45,
        _ => 0
    };

    private static string GetStatusColor(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "secondary",
        ShipmentStatus.PickedUp => "info",
        ShipmentStatus.InTransit => "primary",
        ShipmentStatus.OutForDelivery => "warning",
        ShipmentStatus.Delivered => "success",
        ShipmentStatus.Delayed => "danger",
        _ => "secondary"
    };
}

